/* Client-side presentation layer. Effects never decide combat outcomes. */
const BattleFX=(()=>{
let ctx,canvas,ac;
const point=el=>{if(!el)return{x:innerWidth/2,y:innerHeight/2};let r=el.getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}};
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function tone(kind){if(!P.settings.sound)return;try{ac??=new(window.AudioContext||window.webkitAudioContext)();ac.resume();const t=ac.currentTime;for(let i=0;i<3;i++){let o=ac.createOscillator(),v=ac.createGain();o.type=kind==='fire'?'sawtooth':'sine';o.frequency.setValueAtTime((kind==='hit'?95:kind==='heal'?540:320)*(i+1),t);o.frequency.exponentialRampToValueAtTime(kind==='heal'?880:50,t+.3);v.gain.setValueAtTime(.018/(i+1),t);v.gain.exponentialRampToValueAtTime(.001,t+.35);o.connect(v).connect(ac.destination);o.start();o.stop(t+.36)}}catch{}}
function surface(){canvas=document.createElement('canvas');canvas.className='combat-canvas';canvas.width=innerWidth*devicePixelRatio;canvas.height=innerHeight*devicePixelRatio;canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';document.body.append(canvas);ctx=canvas.getContext('2d');ctx.scale(devicePixelRatio,devicePixelRatio);return canvas}
async function particles(from,to,kind){tone(kind);if(!P.settings.motion)return;const el=surface(),c=ctx,color={fire:'#ff8a25',chidori:'#b6d8ff',heal:'#9dffc2',guard:'#f7ce80',shadow:'#ae84ff',push:'#d5b7ff',rasengan:'#63e8ff',byakugan:'#edddff',revive:'#c7ff9d',rush:'#ffec8b',hit:'#ffda91'}[kind]||'#7eefff';let start=performance.now(),sparks=Array.from({length:45},()=>({a:Math.random()*Math.PI*2,v:30+Math.random()*150,r:1+Math.random()*3}));await new Promise(resolve=>{let done=false;const finish=()=>{if(done)return;done=true;el.remove();resolve()};const timeout=setTimeout(finish,1000);function frame(now){if(done)return;let t=Math.max(0,Math.min(1,(now-start)/650));c.clearRect(0,0,innerWidth,innerHeight);let travel=Math.min(1,t*2),x=from.x+(to.x-from.x)*travel,y=from.y+(to.y-from.y)*travel;c.strokeStyle=color;c.fillStyle=color;c.shadowColor=color;c.shadowBlur=18;
if(t<.6){if(['chidori','shadow'].includes(kind)){for(let j=0;j<3;j++){c.beginPath();c.moveTo(from.x,from.y);for(let k=1;k<=12;k++){let a=k/12;c.lineTo(from.x+(x-from.x)*a+(Math.random()-.5)*30,from.y+(y-from.y)*a+(Math.random()-.5)*30)}c.lineWidth=3-j*.8;c.stroke()}}else if(kind!=='hit'){for(let j=0;j<7;j++){let a=t*20+j;let rr=12+j*2;c.beginPath();c.arc(x+Math.cos(a)*8,y+Math.sin(a)*8,rr,a,a+Math.PI*1.3);c.lineWidth=3;c.stroke()}let grad=c.createRadialGradient(x,y,0,x,y,40);grad.addColorStop(0,'#ffffff');grad.addColorStop(.3,color);grad.addColorStop(1,'transparent');c.fillStyle=grad;c.fillRect(x-40,y-40,80,80)}}
if(t>.35){let p=(t-.35)/.65;c.globalAlpha=1-p;for(let j=0;j<3;j++){c.beginPath();c.arc(to.x,to.y,10+p*(90+j*20),0,Math.PI*2);c.lineWidth=3-j*.6;c.stroke()}c.fillStyle=color;for(let s of sparks){let r=s.v*p;c.beginPath();c.arc(to.x+Math.cos(s.a)*r,to.y+Math.sin(s.a)*r+p*p*45,s.r*(1-p*.5),0,Math.PI*2);c.fill()}c.globalAlpha=1}if(t<1)requestAnimationFrame(frame);else{clearTimeout(timeout);finish()}}requestAnimationFrame(frame)})}
async function move(fromEl,targetEl,kind='hit'){const from=point(fromEl),to=point(targetEl);if(!P.settings.motion){tone(kind);return}if(kind==='hit'&&fromEl){let clone=fromEl.cloneNode(true),r=fromEl.getBoundingClientRect();clone.classList.add('attack-ghost');Object.assign(clone.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:0});document.body.append(clone);fromEl.style.opacity='.35';const anim=clone.animate([{transform:'translate(0,0) scale(1)',filter:'brightness(1)'},{transform:`translate(${(to.x-from.x)*-.12}px,${(to.y-from.y)*-.12}px) rotate(-7deg) scale(1.12)`,offset:.2},{transform:`translate(${to.x-from.x}px,${to.y-from.y}px) rotate(8deg) scale(1.05)`,filter:'brightness(1.6)',offset:.55},{transform:'translate(0,0) scale(1)'}],{duration:560,easing:'cubic-bezier(.2,.7,.3,1)'});await delay(240);await Promise.all([particles(from,to,'hit'),Promise.race([anim.finished.catch(()=>{}),delay(900)])]);clone.remove();fromEl.style.opacity=''}else await particles(from,to,kind);if(targetEl?.isConnected)targetEl.animate([{transform:'translateX(0)',filter:'brightness(2)'},{transform:'translateX(-8px)'},{transform:'translateX(6px)'},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:230})}
function number(position,value,positive=false){if(!value)return;let n=document.createElement('span');n.className='damage-number '+(positive?'positive':'');n.textContent=(positive?'+':'−')+Math.abs(value);n.style.left=position.x+'px';n.style.top=position.y+'px';document.body.append(n);setTimeout(()=>n.remove(),1100)}
function spawn(el,from){if(!el||!P.settings.motion)return;const to=point(el),dx=from?from.x-to.x:0,dy=from?from.y-to.y:70;el.animate([{transform:`translate(${dx}px,${dy}px) scale(.6) rotate(-12deg)`,opacity:0,filter:'brightness(3)'},{transform:'translate(0,0) scale(1.12)',opacity:1,offset:.75},{transform:'scale(1)',filter:'brightness(1)'}],{duration:500,easing:'ease-out'});particles(to,to,'guard')}
function death(el){if(!el||!P.settings.motion)return;let r=el.getBoundingClientRect(),clone=el.cloneNode(true);clone.classList.add('attack-ghost');Object.assign(clone.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px'});document.body.append(clone);clone.animate([{transform:'scale(1)',opacity:1,filter:'grayscale(0) brightness(2)'},{transform:'translateY(-25px) rotate(15deg) scale(.75)',opacity:0,filter:'grayscale(1) brightness(.2)'}],{duration:650}).finished.finally(()=>clone.remove())}
function banner(text){if(!P.settings.motion)return;let e=document.createElement('div');e.className='turn-banner';e.textContent=text;document.body.append(e);setTimeout(()=>e.remove(),1200)}
return{point,move,spawn,death,number,banner,particles};})();
